{

"kind": "propose",
"summary": "Increase memory limit to prevent OOM kills",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_too_low",
    "summary": "Container is OOM killed due to insufficient memory limit",
    "supporting": ["probe_kills", "probe_timeouts", "oom_killed_current_revision", "memory_data_available"],
    "contradicting": ["oom_killed_new_revision"],
    "missing": [],
    "status": "open"
  },
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Liveness probe timeout may still contribute to restarts",
    "supporting": ["probe_timeouts"],
    "contradicting": ["killed_during_startup"],
    "missing": ["container_logs_tail"],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "inventory",
    "uid": "uid-deployment-inventory"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "2Gi"
        }
      }
    }
  },
  "expected_effect": "Prevent OOM kills by increasing memory limit to 2Gi",
  "rationale": "Container logs explicitly state restarts are memory cgroup OOM kills. The current 256Mi limit is insufficient for the workload, despite logs showing normal operation until memory exhaustion. Increasing to 2Gi aligns with the observed OOM kills and prevents premature probe failures.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-pod_states", "ev-rollout_history"],
  "cited_predicates": ["oom_killed_current_revision", "memory_data_available", "probe_timeouts"]
}
}
